insert into public.words (level, term, meaning_ko, example_en, example_ko, pos, category, subcategory) values
('E','equation','방정식','Solve the equation 2x + 3 = 11 for x.','x에 대해 방정식 2x + 3 = 11을 푸시오.','noun','math_en','algebra'),
('E','variable','변수','In the expression 3x, the letter x is a variable.','식 3x에서 문자 x는 변수이다.','noun','math_en','algebra'),
('E','coefficient','계수','In 5x, the number 5 is the coefficient of x.','5x에서 숫자 5는 x의 계수이다.','noun','math_en','algebra'),
('E','constant','상수','In the equation y = 2x + 7, the number 7 is a constant.','방정식 y = 2x + 7에서 숫자 7은 상수이다.','noun','math_en','algebra'),
('E','expression','식, 표현식','The expression 4x - 9 has no equals sign.','식 4x - 9에는 등호가 없다.','noun','math_en','algebra'),
('E','polynomial','다항식','The polynomial x^2 + 3x + 2 can be factored.','다항식 x^2 + 3x + 2는 인수분해할 수 있다.','noun','math_en','algebra'),
('E','monomial','단항식','A monomial such as 7x^2 has only one term.','7x^2 같은 단항식은 항이 하나뿐이다.','noun','math_en','algebra'),
('E','binomial','이항식','The binomial x + 5 is the sum of two terms.','이항식 x + 5는 두 항의 합이다.','noun','math_en','algebra'),
('E','term','항','The expression 3x + 2y has two terms.','식 3x + 2y에는 두 개의 항이 있다.','noun','math_en','algebra'),
('E','factor','인수, 인수분해하다','Factor the expression x^2 - 9 into (x + 3)(x - 3).','식 x^2 - 9를 (x + 3)(x - 3)으로 인수분해하시오.','verb','math_en','algebra'),
('E','exponent','지수','In 2^3, the number 3 is the exponent.','2^3에서 숫자 3은 지수이다.','noun','math_en','algebra'),
('E','base','밑','In 5^2, the number 5 is the base.','5^2에서 숫자 5는 밑이다.','noun','math_en','algebra'),
('E','power','거듭제곱','Two to the fourth power equals sixteen.','2의 4제곱은 16이다.','noun','math_en','algebra'),
('E','square root','제곱근','The square root of 49 is 7.','49의 제곱근은 7이다.','noun','math_en','algebra'),
('E','radical','근호','The radical symbol indicates a root of a number.','근호는 수의 근을 나타낸다.','noun','math_en','algebra'),
('E','inequality','부등식','The inequality x > 4 includes all numbers greater than four.','부등식 x > 4는 4보다 큰 모든 수를 포함한다.','noun','math_en','algebra'),
('E','linear equation','일차방정식','A linear equation graphs as a straight line.','일차방정식은 직선으로 그려진다.','noun','math_en','algebra'),
('E','quadratic equation','이차방정식','A quadratic equation has the form ax^2 + bx + c = 0.','이차방정식은 ax^2 + bx + c = 0의 꼴이다.','noun','math_en','algebra'),
('E','quadratic formula','근의 공식','Use the quadratic formula when factoring is difficult.','인수분해가 어려울 때는 근의 공식을 사용한다.','noun','math_en','algebra'),
('E','discriminant','판별식','If the discriminant is negative, there are no real roots.','판별식이 음수이면 실근이 없다.','noun','math_en','algebra'),
('E','root','근, 해','A root of an equation makes the equation true.','방정식의 근은 그 방정식을 참으로 만든다.','noun','math_en','algebra'),
('E','solution','해','The solution to x + 2 = 5 is x = 3.','x + 2 = 5의 해는 x = 3이다.','noun','math_en','algebra'),
('E','function','함수','A function assigns exactly one output to each input.','함수는 각 입력에 정확히 하나의 출력을 대응시킨다.','noun','math_en','algebra'),
('E','domain','정의역','The domain of a function is the set of allowed inputs.','함수의 정의역은 허용되는 입력의 집합이다.','noun','math_en','algebra'),
('E','range','치역','The range of a function is the set of possible outputs.','함수의 치역은 가능한 출력의 집합이다.','noun','math_en','algebra'),
('E','slope','기울기','The slope of the line measures its steepness.','직선의 기울기는 그 가파른 정도를 나타낸다.','noun','math_en','algebra'),
('E','intercept','절편','The y-intercept is where the line crosses the y-axis.','y절편은 직선이 y축과 만나는 곳이다.','noun','math_en','algebra'),
('E','system of equations','연립방정식','Solve the system of equations by substitution.','연립방정식을 대입법으로 푸시오.','noun','math_en','algebra'),
('E','absolute value','절댓값','The absolute value of negative six is six.','-6의 절댓값은 6이다.','noun','math_en','algebra'),
('E','reciprocal','역수','The reciprocal of 4 is one fourth.','4의 역수는 4분의 1이다.','noun','math_en','algebra'),
('E','logarithm','로그','The logarithm of 1000 base 10 is 3.','밑이 10인 1000의 로그는 3이다.','noun','math_en','algebra'),
('E','sequence','수열','The sequence 2, 4, 6, 8 increases by two each time.','수열 2, 4, 6, 8은 매번 2씩 증가한다.','noun','math_en','algebra'),
('E','series','급수','A series is the sum of the terms of a sequence.','급수는 수열의 항들의 합이다.','noun','math_en','algebra'),
('E','arithmetic sequence','등차수열','In an arithmetic sequence the common difference is constant.','등차수열에서는 공차가 일정하다.','noun','math_en','algebra'),
('E','geometric sequence','등비수열','In a geometric sequence each term is multiplied by a common ratio.','등비수열에서는 각 항에 공비가 곱해진다.','noun','math_en','algebra'),
('E','common difference','공차','The common difference of 3, 7, 11 is four.','3, 7, 11의 공차는 4이다.','noun','math_en','algebra'),
('E','common ratio','공비','The common ratio of 2, 6, 18 is three.','2, 6, 18의 공비는 3이다.','noun','math_en','algebra'),
('E','like terms','동류항','Combine like terms to simplify 3x + 5x into 8x.','동류항을 모아 3x + 5x를 8x로 간단히 하시오.','noun','math_en','algebra'),
('E','simplify','간단히 하다','Simplify the fraction 6/8 to 3/4.','분수 6/8을 3/4으로 간단히 하시오.','verb','math_en','algebra'),
('E','substitute','대입하다','Substitute x = 2 into the expression 3x + 1.','식 3x + 1에 x = 2를 대입하시오.','verb','math_en','algebra'),
('E','distributive property','분배법칙','By the distributive property, 2(x + 3) equals 2x + 6.','분배법칙에 의해 2(x + 3)은 2x + 6과 같다.','noun','math_en','algebra'),
('E','matrix','행렬','A matrix is a rectangular array of numbers.','행렬은 수를 직사각형 모양으로 배열한 것이다.','noun','math_en','algebra'),
('E','vertex form','꼭짓점 형태','The vertex form of a parabola shows its vertex directly.','포물선의 꼭짓점 형태는 꼭짓점을 바로 보여준다.','noun','math_en','algebra'),
('E','factorization','인수분해','The factorization of x^2 - 1 is (x - 1)(x + 1).','x^2 - 1의 인수분해는 (x - 1)(x + 1)이다.','noun','math_en','algebra'),
('E','triangle','삼각형','A triangle has three sides and three angles.','삼각형은 세 변과 세 각을 가진다.','noun','math_en','geometry'),
('E','angle','각','The two lines meet to form a right angle.','두 직선이 만나 직각을 이룬다.','noun','math_en','geometry'),
('E','right angle','직각','A right angle measures exactly ninety degrees.','직각은 정확히 90도이다.','noun','math_en','geometry'),
('E','acute angle','예각','An acute angle is less than ninety degrees.','예각은 90도보다 작다.','noun','math_en','geometry'),
('E','obtuse angle','둔각','An obtuse angle is greater than ninety degrees.','둔각은 90도보다 크다.','noun','math_en','geometry'),
('E','perpendicular','수직의','Two perpendicular lines meet at a right angle.','두 수직선은 직각으로 만난다.','adjective','math_en','geometry'),
('E','parallel','평행한','Parallel lines never intersect.','평행선은 절대 만나지 않는다.','adjective','math_en','geometry'),
('E','hypotenuse','빗변','The hypotenuse is the longest side of a right triangle.','빗변은 직각삼각형에서 가장 긴 변이다.','noun','math_en','geometry'),
('E','Pythagorean theorem','피타고라스 정리','The Pythagorean theorem states that a^2 + b^2 = c^2.','피타고라스 정리는 a^2 + b^2 = c^2임을 말한다.','noun','math_en','geometry'),
('E','perimeter','둘레','The perimeter is the total distance around a shape.','둘레는 도형 주위의 전체 길이이다.','noun','math_en','geometry'),
('E','area','넓이','The area of a rectangle is length times width.','직사각형의 넓이는 가로 곱하기 세로이다.','noun','math_en','geometry'),
('E','volume','부피','The volume of a cube is the cube of its edge length.','정육면체의 부피는 한 모서리 길이의 세제곱이다.','noun','math_en','geometry'),
('E','circumference','원주, 둘레','The circumference of a circle equals 2πr.','원의 둘레는 2πr과 같다.','noun','math_en','geometry'),
('E','radius','반지름','The radius is the distance from the center to the edge of a circle.','반지름은 원의 중심에서 가장자리까지의 거리이다.','noun','math_en','geometry'),
('E','diameter','지름','The diameter of a circle is twice its radius.','원의 지름은 반지름의 두 배이다.','noun','math_en','geometry'),
('E','chord','현','A chord is a line segment joining two points on a circle.','현은 원 위의 두 점을 잇는 선분이다.','noun','math_en','geometry'),
('E','tangent','접선','A tangent touches the circle at exactly one point.','접선은 원에 정확히 한 점에서 닿는다.','noun','math_en','geometry'),
('E','arc','호','An arc is a portion of the circumference of a circle.','호는 원주의 일부분이다.','noun','math_en','geometry'),
('E','polygon','다각형','A polygon is a closed figure made of straight sides.','다각형은 직선 변으로 이루어진 닫힌 도형이다.','noun','math_en','geometry'),
('E','quadrilateral','사각형','A quadrilateral is a polygon with four sides.','사각형은 네 변을 가진 다각형이다.','noun','math_en','geometry'),
('E','rectangle','직사각형','A rectangle has four right angles.','직사각형은 네 개의 직각을 가진다.','noun','math_en','geometry'),
('E','parallelogram','평행사변형','A parallelogram has two pairs of parallel sides.','평행사변형은 두 쌍의 평행한 변을 가진다.','noun','math_en','geometry'),
('E','rhombus','마름모','A rhombus has four sides of equal length.','마름모는 네 변의 길이가 모두 같다.','noun','math_en','geometry'),
('E','trapezoid','사다리꼴','A trapezoid has exactly one pair of parallel sides.','사다리꼴은 한 쌍의 평행한 변을 가진다.','noun','math_en','geometry'),
('E','congruent','합동인','Two congruent triangles have the same size and shape.','두 합동인 삼각형은 크기와 모양이 같다.','adjective','math_en','geometry'),
('E','similar','닮은','Similar figures have the same shape but different sizes.','닮은 도형은 모양은 같고 크기는 다르다.','adjective','math_en','geometry'),
('E','vertex','꼭짓점','A triangle has three vertices.','삼각형은 세 개의 꼭짓점을 가진다.','noun','math_en','geometry'),
('E','edge','모서리','A cube has twelve edges.','정육면체는 12개의 모서리를 가진다.','noun','math_en','geometry'),
('E','face','면','A cube has six square faces.','정육면체는 6개의 정사각형 면을 가진다.','noun','math_en','geometry'),
('E','diagonal','대각선','A diagonal connects two non-adjacent vertices of a polygon.','대각선은 다각형의 이웃하지 않는 두 꼭짓점을 잇는다.','noun','math_en','geometry'),
('E','symmetry','대칭','A square has four lines of symmetry.','정사각형은 4개의 대칭축을 가진다.','noun','math_en','geometry'),
('E','reflection','반사, 대칭이동','A reflection flips a figure across a line.','반사는 도형을 직선을 기준으로 뒤집는다.','noun','math_en','geometry'),
('E','rotation','회전','A rotation turns a figure around a fixed point.','회전은 도형을 고정된 점을 중심으로 돌린다.','noun','math_en','geometry'),
('E','translation','평행이동','A translation slides a figure without turning it.','평행이동은 도형을 돌리지 않고 미끄러뜨린다.','noun','math_en','geometry'),
('E','coordinate plane','좌표평면','Each point on the coordinate plane has an x and y value.','좌표평면의 각 점은 x값과 y값을 가진다.','noun','math_en','geometry'),
('E','midpoint','중점','The midpoint divides a segment into two equal parts.','중점은 선분을 두 개의 같은 부분으로 나눈다.','noun','math_en','geometry'),
('E','line segment','선분','A line segment has two endpoints.','선분은 두 개의 끝점을 가진다.','noun','math_en','geometry'),
('E','ray','반직선','A ray starts at one point and extends forever in one direction.','반직선은 한 점에서 시작해 한 방향으로 무한히 뻗는다.','noun','math_en','geometry'),
('E','sphere','구','A sphere is a perfectly round three-dimensional shape.','구는 완벽하게 둥근 입체도형이다.','noun','math_en','geometry'),
('E','cylinder','원기둥','A cylinder has two circular bases.','원기둥은 두 개의 원형 밑면을 가진다.','noun','math_en','geometry'),
('E','cone','원뿔','A cone has one circular base and one vertex.','원뿔은 하나의 원형 밑면과 하나의 꼭짓점을 가진다.','noun','math_en','geometry'),
('E','prism','각기둥','A triangular prism has two triangular faces.','삼각기둥은 두 개의 삼각형 면을 가진다.','noun','math_en','geometry'),
('E','theorem','정리','A theorem is a statement that has been proven true.','정리는 참임이 증명된 명제이다.','noun','math_en','geometry'),
('E','probability','확률','The probability of flipping heads is one half.','동전에서 앞면이 나올 확률은 2분의 1이다.','noun','math_en','stats'),
('E','statistics','통계','Statistics is the study of collecting and analyzing data.','통계는 자료를 모으고 분석하는 학문이다.','noun','math_en','stats'),
('E','data','자료, 데이터','We collected data on the heights of students.','우리는 학생들의 키에 대한 자료를 모았다.','noun','math_en','stats'),
('E','mean','평균','The mean of 2, 4, and 6 is four.','2, 4, 6의 평균은 4이다.','noun','math_en','stats'),
('E','median','중앙값','The median is the middle value of an ordered data set.','중앙값은 정렬된 자료의 가운데 값이다.','noun','math_en','stats'),
('E','mode','최빈값','The mode is the value that appears most often.','최빈값은 가장 자주 나타나는 값이다.','noun','math_en','stats'),
('E','range (statistics)','범위','The range of the data is the largest value minus the smallest.','자료의 범위는 최댓값에서 최솟값을 뺀 것이다.','noun','math_en','stats'),
('E','variance','분산','The variance measures how spread out the data is.','분산은 자료가 얼마나 흩어져 있는지를 나타낸다.','noun','math_en','stats'),
('E','standard deviation','표준편차','A small standard deviation means the data is close to the mean.','표준편차가 작으면 자료가 평균에 가깝다는 뜻이다.','noun','math_en','stats'),
('E','outcome','결과','Rolling a 3 is one possible outcome of a die.','3이 나오는 것은 주사위의 한 가지 가능한 결과이다.','noun','math_en','stats'),
('E','event','사건','Rolling an even number is an event with three outcomes.','짝수가 나오는 것은 결과가 셋인 사건이다.','noun','math_en','stats'),
('E','sample space','표본공간','The sample space of a coin flip is heads and tails.','동전 던지기의 표본공간은 앞면과 뒷면이다.','noun','math_en','stats'),
('E','random variable','확률변수','A random variable assigns a number to each outcome.','확률변수는 각 결과에 수를 대응시킨다.','noun','math_en','stats'),
('E','distribution','분포','The distribution shows how the data values are spread.','분포는 자료 값들이 어떻게 퍼져 있는지 보여준다.','noun','math_en','stats'),
('E','normal distribution','정규분포','A normal distribution has a symmetric bell shape.','정규분포는 대칭인 종 모양을 가진다.','noun','math_en','stats'),
('E','frequency','도수','The frequency of a value is how many times it occurs.','어떤 값의 도수는 그것이 나타난 횟수이다.','noun','math_en','stats'),
('E','histogram','히스토그램','A histogram displays the frequency of data in intervals.','히스토그램은 구간별 자료의 도수를 나타낸다.','noun','math_en','stats'),
('E','sample','표본','A sample is a small part of a larger population.','표본은 더 큰 모집단의 일부분이다.','noun','math_en','stats'),
('E','population','모집단','The population is the entire group being studied.','모집단은 연구 대상이 되는 전체 집단이다.','noun','math_en','stats'),
('E','correlation','상관관계','There is a positive correlation between study time and grades.','공부 시간과 성적 사이에는 양의 상관관계가 있다.','noun','math_en','stats'),
('E','permutation','순열','A permutation counts arrangements where order matters.','순열은 순서가 중요한 배열의 수를 센다.','noun','math_en','stats'),
('E','combination','조합','A combination counts selections where order does not matter.','조합은 순서가 중요하지 않은 선택의 수를 센다.','noun','math_en','stats'),
('E','factorial','계승, 팩토리얼','Five factorial equals 120.','5 팩토리얼은 120이다.','noun','math_en','stats'),
('E','expected value','기댓값','The expected value is the long-run average outcome.','기댓값은 장기적으로 예상되는 평균 결과이다.','noun','math_en','stats'),
('E','independent events','독립사건','Two independent events do not affect each other.','두 독립사건은 서로 영향을 주지 않는다.','noun','math_en','stats'),
('E','mutually exclusive','배반인','Mutually exclusive events cannot happen at the same time.','배반인 사건은 동시에 일어날 수 없다.','adjective','math_en','stats'),
('E','conditional probability','조건부확률','Conditional probability is the chance of an event given another.','조건부확률은 다른 사건이 주어졌을 때의 확률이다.','noun','math_en','stats'),
('E','percentile','백분위수','A score in the 90th percentile beats 90 percent of others.','90 백분위수의 점수는 다른 90퍼센트보다 높다.','noun','math_en','stats'),
('E','quartile','사분위수','The first quartile separates the lowest 25 percent of data.','제1사분위수는 자료의 하위 25퍼센트를 나눈다.','noun','math_en','stats'),
('E','scatter plot','산점도','A scatter plot shows the relationship between two variables.','산점도는 두 변수 사이의 관계를 보여준다.','noun','math_en','stats'),
('E','average','평균','The average score on the test was 85.','시험의 평균 점수는 85점이었다.','noun','math_en','stats'),
('E','trial','시행','Each flip of the coin is one trial.','동전을 한 번 던지는 것이 한 번의 시행이다.','noun','math_en','stats'),
